      'ui.untitled':'Untitled',
      'dash.nSteps':'{n} steps',
      'basics.objectTitle':'Object of the game',
      'basics.objectB1':'Two teams try to throw the ball into the opponent’s goal. A goal counts only when the ball <strong>fully crosses the goal line</strong>.',
      'basics.objectB2':'Play starts with both teams on their own goal lines; the referee releases the ball at mid‑pool and the teams swim for it.',
      'basics.objectB3':'You must get a shot away before your possession time runs out, or the ball turns over.',
      'basics.teamTitle':'Team & positions',
      'basics.teamB1':'Each team has <strong>7 in the water</strong>: 6 field players + 1 goalkeeper. Match roster: up to <strong>14</strong> (12 field + 2 goalkeepers).',
      'basics.teamB2':'In this app we number the field players <strong>1–6</strong> and mark them by team colour.',
      'basics.teamB3':'A common shape: perimeter players (wings, flats, point) around the arc, with a <strong>centre‑forward (“hole set”)</strong> posted at the 2 m line in front of goal.',
      'basics.structureTitle':'Game structure',
      'basics.structureB1':'Played in <strong>4 quarters</strong> of 8 minutes actual play (senior level); teams change ends at half‑time.',
      'basics.structureB2':'A <strong>28‑second possession clock</strong> limits each attack — shoot before it expires.',
      'basics.structureB3':'Each team has <strong>two 1‑minute timeouts</strong> — callable only while in possession, even straight after a goal.',
      'basics.structureB4':'Flying substitutions go through your team’s own half of the substitution area (own goal line → centre); World Aquatics events also use a <strong>VAR referee</strong>.',
      'basics.poolTitle':'The pool & its lines',
      'basics.poolB1':'Field of play: <strong>25 m × 20 m</strong> goal line to goal line — men and women alike (2025 rules).',
      'basics.poolB2':'<strong>Goal line</strong> · <strong>2 m line (red)</strong> — no attacker may sit inside it ahead of the ball.',
      'basics.poolB3':'<strong>5 m line (yellow)</strong> — penalty throws are taken from anywhere on it. <strong>6 m line (green)</strong> — free throws from outside it may be shot directly; blocking with two hands is only allowed inside your own 6 m area.',
      'basics.poolB4':'<strong>Half‑distance line</strong> at the middle. Excluded players wait and re‑enter from the <strong>exclusion / re‑entry</strong> corner.',
      'basics.foulsTitle':'Fouls & penalties',
      'basics.foulsB1':'<strong>Ordinary (minor) fouls</strong> — pushing the ball under, two hands on the ball (field players), impeding a free player — give a <strong>free throw / change of possession</strong>.',
      'basics.foulsB2':'<strong>Major (exclusion) fouls</strong> — holding/sinking an opponent, tactical fouls — send the offender to the re‑entry corner for <strong>18 seconds</strong> (a “man‑up”); they return at the earliest of 18 s served, a goal, or their team being awarded a free throw / goal throw / penalty.',
      'basics.foulsB3':'A major foul inside the <strong>6 m area</strong> that stops a likely goal is a <strong>penalty shot</strong>, taken from the 5 m line — in the last minute the coach may choose possession instead (clock reset to 28 s).',
      'basics.keeperTitle':'The goalkeeper',
      'basics.keeperB1':'Wears the <strong>red cap</strong> and defends the goal.',
      'basics.keeperB2':'Inside the 6 m area the keeper may <strong>use two hands</strong> and (where depth allows) push off the bottom — things field players can’t do.',
      'basics.keeperB3':'The keeper starts the counter‑attack: a fast, accurate outlet pass turns defence into offence.',
      'basics.skillsTitle':'Core skills',
      'basics.skillsB1':'<strong>Eggbeater kick</strong> — the alternating leg motion that keeps you high and stable without using your hands.',
      'basics.skillsB2':'<strong>Dry passing</strong> — catch and release with one hand, keeping the ball out of the water.',
      'basics.skillsB3':'<strong>Shooting</strong> — power shots, lobs over the keeper, and quick catch‑and‑shoot off a feed.',
      'basics.autoChecked':'Auto‑checked {date}',
      'basics.bundledSnapshot':'Bundled snapshot',
      'basics.lastKnown':'<em>(last known)</em>',
      'basics.open':'open ↗',
      'basics.respPlayersTitle':'Players',
      'basics.respPlayers1':'Know your position and your job on every play — offense <em>and</em> defense.',
      'basics.respPlayers2':'Follow the game plan and the coach’s calls; run the set plays.',
      'basics.respPlayers3':'Communicate constantly — call screens, presses and switches.',
      'basics.respPlayers4':'Play within the rules: manage your fouls and avoid needless exclusions.',
      'basics.respPlayers5':'Sprint transitions — first back on defense, first up on the counter.',
      'basics.respPlayers6':'Support the goalkeeper and protect the front of goal.',
      'basics.respPlayers7':'Respect teammates, opponents and officials; give full effort when tired.',
      'basics.respCoach1':'Prepare the team: training plans, tactics and set plays.',
      'basics.respCoach2':'Pick the line-up and manage substitutions and time-outs.',
      'basics.respCoach3':'Teach roles and positions; develop every player.',
      'basics.respCoach4':'Read the game and adjust tactics in real time (man-up, man-down, press vs drop).',
      'basics.respCoach5':'Motivate, set standards and manage the bench.',
      'basics.respCoach6':'Look after player welfare, safety and fair play.',
      'basics.respCoach7':'Communicate clearly and respect the officials.',
      'basics.respRefereeTitle':'Referee',
      'basics.respReferee1':'Enforce the rules and keep the game fair and safe.',
      'basics.respReferee2':'Award ordinary fouls, exclusions (18 s) and penalties (from the 5 m line).',
      'basics.respReferee3':'Manage exclusions and re-entry from the corner.',
      'basics.respReferee4':'Signal decisions clearly; coordinate with the table, timekeepers and VAR.',
      'basics.respReferee5':'Control the match and both benches; stay impartial.',
      'basics.respReferee6':'Protect players from dangerous play.',
      'basics.sourceNote':'Fundamentals summarised from {a}, {b}, and World Aquatics rules. Details vary by level/governing body.',
