      'film.hardenedTitle':'Tier 2: connected-component detection + multi-object tracking — rejects splash, bridges occlusion, steadier positions',
      'film.hardened':'Hardened',
      'film.detectorColour':'● colour',
      'film.trackingNote':'Reads the caps (white / dark / red&nbsp;keeper) and the orange ball and maps them onto your board. Calibrate once by clicking the four corners of the field of play. <strong>Hardened</strong> tracks a short passage from the current time and bridges occlusion. Offline &amp; private.',
      'film.autoScout':'🧠 Auto-scout',
