      'film.scoutIdle':'● idle',
      'film.autoScoutNote':'The system watches the <strong>whole</strong> video, cuts it into possessions, recognises each tactic, and writes a scouting summary + a playbook — no tagging by hand. Calibrate the pool first. Long videos run in the background.',
      'film.cloudAnalysis':'☁️ Cloud analysis',
