      'film.cloudNote':'Auto-tag the match, then confirm what’s right — the same workflow whether it runs on-device (now) or in the cloud (when a pipeline is live). Calibrate first under Position tracking.',
      'film.scoutNeedsFile':'● needs the video file',
      'film.noVideoFileNote':'Auto-scout, position tracking and auto-analyse read the <strong>video file itself</strong>. This match is {src} the analyser can’t open — download the match from {from} and use <strong>Upload video</strong> on the left; the tools appear on that upload.',
