      'basics.objectTitle':'Ziel des Spiels',
      'basics.objectB1':'Zwei Teams versuchen, den Ball ins gegnerische Tor zu werfen. Ein Tor zählt nur, wenn der Ball <strong>die Torlinie ganz überquert</strong>.',
      'basics.objectB2':'Gespielt wird ab der eigenen Torlinie: Der Schiedsrichter gibt den Ball in der Beckenmitte frei und beide Teams schwimmen darum.',
      'basics.objectB3':'Du musst abschliessen, bevor die Angriffszeit abläuft — sonst wechselt der Ballbesitz.',
      'basics.teamTitle':'Team & Positionen',
      'basics.teamB1':'Jedes Team hat <strong>7 im Wasser</strong>: 6 Feldspieler + 1 Goalie. Matchkader: bis zu <strong>14</strong> (12 Feldspieler + 2 Goalies).',
      'basics.teamB2':'In dieser App nummerieren wir die Feldspieler <strong>1–6</strong> und kennzeichnen sie mit der Teamfarbe.',
      'basics.teamB3':'Eine übliche Aufstellung: die Aussenspieler (Flügel, Halbpositionen, Mitte) am Bogen, dazu ein <strong>Center („hole set“)</strong> auf der 2‑m‑Linie vor dem Tor.',
      'basics.structureTitle':'Spielablauf',
      'basics.structureB1':'Gespielt wird in <strong>4 Vierteln</strong> à 8 Minuten effektiver Spielzeit (Aktive); zur Halbzeit werden die Seiten gewechselt.',
      'basics.structureB2':'Eine <strong>28‑Sekunden‑Angriffszeit</strong> begrenzt jeden Angriff — schiess, bevor sie abläuft.',
      'basics.structureB3':'Jedes Team hat <strong>zwei 1‑Minuten‑Timeouts</strong> — nur im eigenen Ballbesitz, auch direkt nach einem Tor.',
      'basics.structureB4':'Fliegende Wechsel laufen über die eigene Hälfte der Wechselzone (eigene Torlinie → Mitte); an World-Aquatics-Turnieren gibt es zusätzlich einen <strong>VAR-Schiedsrichter</strong>.',
      'basics.poolTitle':'Das Becken & seine Linien',
      'basics.poolB1':'Spielfeld: <strong>25 m × 20 m</strong> von Torlinie zu Torlinie — bei Männern wie Frauen (Reglement 2025).',
      'basics.poolB2':'<strong>Torlinie</strong> · <strong>2-m-Linie (rot)</strong> — kein Angreifer darf sich dort vor dem Ball aufhalten.',
      'basics.poolB3':'<strong>5-m-Linie (gelb)</strong> — Penaltys werden von einer beliebigen Stelle auf ihr geschossen. <strong>6-m-Linie (grün)</strong> — Freiwürfe von ausserhalb dürfen direkt aufs Tor geschossen werden; mit zwei Händen blocken darfst du nur im eigenen 6-m-Raum.',
      'basics.poolB4':'<strong>Mittellinie</strong> in der Beckenmitte. Ausgeschlossene Spieler warten in der <strong>Ausschluss‑ / Wiedereintrittsecke</strong> und kommen von dort zurück ins Spiel.',
      'basics.foulsTitle':'Fouls & Strafen',
      'basics.foulsB1':'<strong>Einfache Fehler</strong> — den Ball untertauchen, zwei Hände am Ball (Feldspieler), einen freien Spieler behindern — geben einen <strong>Freiwurf / Ballbesitzwechsel</strong>.',
      'basics.foulsB2':'<strong>Ausschlussfehler</strong> — einen Gegner halten oder untertauchen, taktische Fouls — schicken den Schuldigen für <strong>18 Sekunden</strong> in die Wiedereintrittsecke („Überzahl“ für die andern); er kommt zurück, sobald die 18 s abgelaufen sind, ein Tor fällt oder sein Team einen Freiwurf / Torwurf / Penalty erhält — je nachdem, was zuerst eintritt.',
      'basics.foulsB3':'Ein Ausschlussfehler im <strong>6-m-Raum</strong>, der ein wahrscheinliches Tor verhindert, gibt einen <strong>Penalty</strong> von der 5-m-Linie — in der letzten Minute kann der Trainer stattdessen den Ballbesitz wählen (Angriffszeit zurück auf 28 s).',
      'basics.keeperTitle':'Der Goalie',
      'basics.keeperB1':'Trägt die <strong>rote Kappe</strong> und verteidigt das Tor.',
      'basics.keeperB2':'Im 6-m-Raum darf der Goalie <strong>beide Hände benutzen</strong> und sich (wo es die Tiefe zulässt) vom Boden abstossen — Feldspieler dürfen das nicht.',
      'basics.keeperB3':'Der Goalie startet den Gegenangriff: Ein schneller, genauer Eröffnungspass macht aus der Abwehr einen Angriff.',
      'basics.skillsTitle':'Grundtechniken',
      'basics.skillsB1':'<strong>Eggbeater</strong> — die wechselseitige Beinbewegung, die dich ohne Hände hoch und stabil im Wasser hält.',
      'basics.skillsB2':'<strong>Trockenes Passspiel</strong> — mit einer Hand fangen und weiterspielen, ohne dass der Ball ins Wasser kommt.',
      'basics.skillsB3':'<strong>Torschuss</strong> — harte Schüsse, Lobs über den Goalie und schnelles Fangen‑und‑Schiessen nach dem Zuspiel.',
      'basics.autoChecked':'Automatisch geprüft am {date}',
      'basics.bundledSnapshot':'Mitgelieferte Version',
      'basics.lastKnown':'<em>(zuletzt bekannt)</em>',
      'basics.open':'öffnen ↗',
      'basics.respPlayersTitle':'Spieler',
      'basics.respPlayers1':'Kenne deine Position und deine Aufgabe in jedem Spielzug — im Angriff <em>und</em> in der Abwehr.',
      'basics.respPlayers2':'Halte dich an den Matchplan und die Ansagen des Trainers; spiel die einstudierten Spielzüge.',
      'basics.respPlayers3':'Rede ständig — sag Sperren, Pressing und Übergaben an.',
      'basics.respPlayers4':'Spiel im Rahmen der Regeln: Achte auf deine Fouls und vermeide unnötige Ausschlüsse.',
      'basics.respPlayers5':'Umschalten heisst sprinten — als Erster zurück in die Abwehr, als Erster vorne im Gegenangriff.',
      'basics.respPlayers6':'Unterstütze den Goalie und schütze den Raum vor dem Tor.',
      'basics.respPlayers7':'Respektiere Mitspieler, Gegner und Offizielle; gib auch müde alles.',
      'basics.respCoach1':'Bereite das Team vor: Trainingspläne, Taktik und einstudierte Spielzüge.',
      'basics.respCoach2':'Stelle die Mannschaft auf und steuere Wechsel und Timeouts.',
      'basics.respCoach3':'Vermittle Rollen und Positionen; entwickle jeden Spieler.',
      'basics.respCoach4':'Lies das Spiel und pass die Taktik laufend an (Überzahl, Unterzahl, Pressing oder Abfallen).',
      'basics.respCoach5':'Motiviere, setze Massstäbe und führe die Bank.',
      'basics.respCoach6':'Achte auf Wohl, Sicherheit und Fairplay der Spieler.',
      'basics.respCoach7':'Kommuniziere klar und respektiere die Offiziellen.',
      'basics.respRefereeTitle':'Schiedsrichter',
      'basics.respReferee1':'Setze die Regeln durch und halte das Spiel fair und sicher.',
      'basics.respReferee2':'Ahnde einfache Fehler, Ausschlüsse (18 s) und Penaltys (von der 5-m-Linie).',
      'basics.respReferee3':'Überwache Ausschlüsse und den Wiedereintritt aus der Ecke.',
      'basics.respReferee4':'Zeige Entscheide klar an; stimm dich mit dem Tisch, den Zeitnehmern und dem VAR ab.',
      'basics.respReferee5':'Führe das Spiel und beide Bänke; bleib unparteiisch.',
      'basics.respReferee6':'Schütze die Spieler vor gefährlichem Spiel.',
