      'film.possessionNote':'Ballbesitz = wer den Ball hat (mit ein paar Bildern Geduld, bevor er wechselt); jedes Team wird an dem Tor gemessen, das es angreift. Ein <em>Muster</em> ist der Weg des Balls — Flügel → Mitte → 2 m → Schuss — in der gleichen Situation wiederholt. Das Tracking der Spieler kann ungenau sein; der Ballweg ist das, was bleibt.',
