      'film.hardened':'Robust',
      'film.detectorColour':'● Farbe',
      'film.trackingNote':'Liest die Kappen (weiss / dunkel / roter&nbsp;Goalie) und den orangen Ball und überträgt sie auf deine Tafel. Einmal kalibrieren, indem du die vier Ecken des Spielfelds anklickst. <strong>Robust</strong> verfolgt eine kurze Passage ab der aktuellen Zeit und überbrückt Verdeckungen. Offline &amp; privat.',
