      'film.autoScoutNote':'Das System schaut das <strong>ganze</strong> Video, schneidet es in Ballbesitze, erkennt jede Taktik und schreibt eine Scouting-Zusammenfassung + ein Playbook — ohne Markieren von Hand. Kalibriere zuerst das Becken. Lange Videos laufen im Hintergrund.',
