      'basics.objectTitle':'But du jeu',
      'basics.objectB1':'Deux équipes essaient d\'envoyer le ballon dans le but adverse. Le but ne compte que si le ballon <strong>franchit entièrement la ligne de but</strong>.',
      'basics.objectB2':'Le jeu commence avec les deux équipes sur leur propre ligne de but ; l\'arbitre lâche le ballon au milieu du bassin et les équipes sprintent pour le prendre.',
      'basics.objectB3':'Tu dois tirer avant la fin de ton temps de possession, sinon le ballon change de camp.',
      'basics.teamTitle':'Équipe & postes',
      'basics.teamB1':'Chaque équipe a <strong>7 joueurs dans l\'eau</strong> : 6 joueurs de champ + 1 gardien. Feuille de match : jusqu\'à <strong>14</strong> (12 joueurs de champ + 2 gardiens).',
      'basics.teamB2':'Dans cette application, les joueurs de champ sont numérotés <strong>1–6</strong> et repérés par la couleur de l\'équipe.',
      'basics.teamB3':'Une organisation classique : les joueurs du périmètre (ailiers, arrières, pointe) autour de l\'arc, avec un <strong>centre‑avant («⁠ hole set ⁠»)</strong> posté sur la ligne des 2 m devant le but.',
      'basics.structureTitle':'Déroulement du match',
      'basics.structureB1':'Se joue en <strong>4 quarts‑temps</strong> de 8 minutes de jeu effectif (niveau senior) ; les équipes changent de camp à la mi‑temps.',
      'basics.structureB2':'Un <strong>temps de possession de 28 secondes</strong> limite chaque attaque — tire avant qu\'il expire.',
      'basics.structureB3':'Chaque équipe a <strong>deux temps morts d\'1 minute</strong> — à demander seulement quand on a le ballon, même juste après un but.',
      'basics.structureB4':'Les changements volants se font par la moitié de bassin de ton équipe dans la zone de changement (propre ligne de but → milieu) ; les compétitions World Aquatics utilisent aussi un <strong>arbitre VAR</strong>.',
      'basics.poolTitle':'Le bassin & ses lignes',
      'basics.poolB1':'Aire de jeu : <strong>25 m × 20 m</strong> d\'une ligne de but à l\'autre — pareil chez les hommes et chez les femmes (règles 2025).',
      'basics.poolB2':'<strong>Ligne de but</strong> · <strong>ligne des 2 m (rouge)</strong> — aucun attaquant ne peut se placer à l\'intérieur devant le ballon.',
      'basics.poolB3':'<strong>Ligne des 5 m (jaune)</strong> — les penaltys se tirent depuis n\'importe quel point de cette ligne. <strong>Ligne des 6 m (verte)</strong> — un coup franc obtenu au‑delà peut être tiré directement ; le blocage à deux mains n\'est autorisé que dans ta propre zone des 6 m.',
      'basics.poolB4':'<strong>Ligne médiane</strong> au milieu. Les joueurs exclus attendent et reviennent par le coin d\'<strong>exclusion / rentrée</strong>.',
      'basics.foulsTitle':'Fautes & sanctions',
      'basics.foulsB1':'<strong>Fautes ordinaires (simples)</strong> — couler le ballon, toucher le ballon à deux mains (joueurs de champ), gêner un joueur qui n\'a pas le ballon — donnent un <strong>coup franc / changement de possession</strong>.',
      'basics.foulsB2':'<strong>Fautes graves (exclusions)</strong> — tenir ou couler un adversaire, faute tactique — envoient le fautif au coin de rentrée pour <strong>18 secondes</strong> (une «⁠ supériorité numérique ⁠») ; il revient au premier de ces cas : 18 s purgées, un but, ou un coup franc / une remise en jeu de but / un penalty accordé à son équipe.',
      'basics.foulsB3':'Une faute grave dans la <strong>zone des 6 m</strong> qui empêche un but probable donne un <strong>penalty</strong>, tiré depuis la ligne des 5 m — dans la dernière minute, l\'entraîneur peut choisir la possession à la place (chrono remis à 28 s).',
      'basics.keeperTitle':'Le gardien',
      'basics.keeperB1':'Porte le <strong>bonnet rouge</strong> et défend le but.',
      'basics.keeperB2':'Dans la zone des 6 m, le gardien peut <strong>utiliser les deux mains</strong> et, si la profondeur le permet, prendre appui au fond — ce que les joueurs de champ n\'ont pas le droit de faire.',
      'basics.keeperB3':'Le gardien lance la contre‑attaque : une relance rapide et précise fait passer de la défense à l\'attaque.',
      'basics.skillsTitle':'Techniques de base',
      'basics.skillsB1':'<strong>Eggbeater</strong> — le battement de jambes alterné qui te tient haut et stable sans les mains.',
      'basics.skillsB2':'<strong>Passe sèche</strong> — attraper et relâcher d\'une seule main, sans poser le ballon dans l\'eau.',
      'basics.skillsB3':'<strong>Tir</strong> — tirs puissants, lobs par‑dessus le gardien et reprises rapides sur une passe.',
      'basics.autoChecked':'Auto‑vérifié {date}',
      'basics.bundledSnapshot':'Copie intégrée',
      'basics.lastKnown':'<em>(dernière version connue)</em>',
      'basics.open':'ouvrir ↗',
      'basics.respPlayersTitle':'Joueurs',
      'basics.respPlayers1':'Connais ton poste et ton rôle sur chaque combinaison — en attaque <em>et</em> en défense.',
      'basics.respPlayers2':'Suis le plan de match et les consignes de l\'entraîneur ; joue les combinaisons travaillées.',
      'basics.respPlayers3':'Communique sans arrêt — annonce les écrans, le pressing et les changements de marquage.',
      'basics.respPlayers4':'Joue dans les règles : gère tes fautes et évite les exclusions inutiles.',
      'basics.respPlayers5':'Sprinte les transitions — premier replacé en défense, premier parti en contre.',
      'basics.respPlayers6':'Aide le gardien et protège la zone devant le but.',
      'basics.respPlayers7':'Respecte tes coéquipiers, les adversaires et les officiels ; donne tout même fatigué.',
      'basics.respCoach1':'Prépare l\'équipe : plans d\'entraînement, tactique et combinaisons travaillées.',
