      'film.autoAnalyseNote':'Lit la vidéo importée et repère les moments animés grâce au mouvement, pour y aller directement.',
      'film.positionTracking':'📍 Suivi des positions',
      'film.findFieldTitle':'Trouve automatiquement le bassin dans l’image actuelle — fonctionne avec une caméra mobile',
      'film.findField':'🎯 Trouver le terrain',
      'film.clickCornersTitle':'Clique toi-même les quatre coins',
      'film.clickCorners':'Cliquer les coins',
      'film.movingCameraTitle':'Redétecte le bassin environ une fois par seconde pendant l’analyse — pour une caméra qui pivote ou zoome. Les images où le bassin n’est pas assez visible sont signalées comme non lues.',
      'film.movingCamera':'📷 caméra mobile',
      'film.trackPositions':'Suivre les positions',
      'film.hardenedTitle':'Tier 2 : détection par composantes connexes + suivi multi-objets — écarte les éclaboussures, comble les occultations, positions plus stables',
      'film.hardened':'Renforcé',
      'film.detectorColour':'● couleur',
      'film.trackingNote':'Lit les bonnets (blancs / foncés / gardien&nbsp;rouge) et le ballon orange, puis les reporte sur ton tableau. Calibre une fois en cliquant les quatre coins du terrain de jeu. <strong>Renforcé</strong> suit un court passage à partir du temps actuel et comble les occultations. Hors ligne &amp; privé.',
      'film.autoScout':'🧠 Scouting auto',
      'film.scoutVideo':'Scouter cette vidéo',
      'film.whichCapsTitle':'Quels bonnets sont les nôtres ?',
      'film.weAreWhite':'Nous sommes les bonnets blancs',
      'film.weAreDark':'Nous sommes les bonnets bleus (foncés)',
      'film.scoutIdle':'● en veille',
      'film.autoScoutNote':'Le système regarde <strong>toute</strong> la vidéo, la découpe en possessions, reconnaît chaque tactique et rédige un rapport de scouting + un playbook — aucun marquage à la main. Calibre d’abord le bassin. Les longues vidéos tournent en arrière-plan.',
      'film.cloudAnalysis':'☁️ Analyse dans le cloud',
      'film.runAnalysis':'Lancer l’analyse',
      'film.cloudOnDevice':'● Sur l’appareil (hors ligne)',
      'film.cloudNote':'Marque le match automatiquement, puis confirme ce qui est juste — le même déroulé, que ça tourne sur l’appareil (maintenant) ou dans le cloud (quand un pipeline sera en service). Calibre d’abord sous Suivi des positions.',
      'film.scoutNeedsFile':'● fichier vidéo requis',
      'film.noVideoFileNote':'Le scouting auto, le suivi des positions et l’analyse auto lisent <strong>le fichier vidéo lui-même</strong>. Ce match est {src} que l’analyseur ne peut pas ouvrir — télécharge le match depuis {from} et utilise <strong>Importer une vidéo</strong> à gauche ; les outils apparaissent après cet import.',
      'film.srcYoutubeLink':'un lien YouTube',
