      'ui.editorCloseHint':'Ferme avec ✕ ou Annuler — pour qu’un clic à côté ne jette jamais une combinaison.',
      'film.zoneHintTL':'Haut côté proche : presse le tireur plus tôt ; l’angle haut du premier poteau est au gardien.',
      'film.zoneHintTC':'Haut au centre : une main doit être dans l’axe du tir — le gardien reste haut, il ne descend pas trop tôt.',
      'film.zoneHintTR':'Haut côté opposé : l’ailier ferme l’angle ; le gardien se décale au second poteau.',
      'film.zoneHintML':'Mi-hauteur côté proche : gagne la position d’épaule avant la réception, pas après.',
      'film.zoneHintMC':'Plein axe : passe devant le centre — pas de réception libre à 2 m.',
      'film.zoneHintMR':'Mi-hauteur côté opposé : aide du côté faible plus tôt ; la ligne de passe croisée reste fermée.',
      'film.zoneHintBL':'Bas côté proche : bloque VERS LE BAS avec la main intérieure ; le gardien reste bas au premier poteau.',
      'film.zoneHintBC':'Bas au centre : les jambes ! Le gardien tient sa position ; le défenseur gêne l’armé du tir.',
      'film.zoneHintBR':'Bas côté opposé : ferme l’angle croisé — repli plus tôt depuis le poste 4.',
