      'ui.correctThatSTheFinisher':'<strong>Esatto!</strong> È lui che conclude.',
      'ui.notQuitePlayerFinishes':'<strong>Non proprio.</strong> Qui conclude il giocatore {n}.',
      'ui.flawless':'Impeccabile!',
