      'ui.nOfMCorrect':'{a}/{b} corrette',
      'ui.untitled':'Senza titolo',
      'dash.nSteps':'{n} fasi',
      'basics.objectTitle':'Scopo del gioco',
      'basics.objectB1':'Due squadre cercano di mandare la palla nella porta avversaria. Il gol vale solo se la palla <strong>supera completamente la linea di porta</strong>.',
      'basics.objectB2':'Si parte con le due squadre sulle proprie linee di porta; l’arbitro lascia la palla a metà vasca e le squadre nuotano per prenderla.',
      'basics.objectB3':'Devi tirare prima che scada il tempo di possesso, altrimenti la palla passa agli avversari.',
      'basics.teamTitle':'Squadra & ruoli',
      'basics.teamB1':'Ogni squadra ha <strong>7 giocatori in acqua</strong>: 6 di movimento + 1 portiere. In distinta fino a <strong>14</strong> (12 di movimento + 2 portieri).',
      'basics.teamB2':'In questa app i giocatori di movimento sono numerati <strong>1–6</strong> e distinti dal colore della squadra.',
      'basics.teamB3':'Uno schieramento tipico: i giocatori di perimetro (ali, laterali, centrale) lungo l’arco, con un <strong>centroboa (“hole set”)</strong> piazzato sulla linea dei 2 m davanti alla porta.',
      'basics.structureTitle':'Struttura della partita',
      'basics.structureB1':'Si gioca in <strong>4 tempi</strong> da 8 minuti effettivi (livello senior); a metà partita le squadre cambiano campo.',
      'basics.structureB2':'Ogni attacco ha <strong>28 secondi di possesso</strong> — tira prima che scadano.',
      'basics.structureB3':'Ogni squadra ha <strong>due time‑out da 1 minuto</strong> — si chiamano solo con la palla in possesso, anche subito dopo un gol.',
      'basics.structureB4':'I cambi volanti passano dalla metà della zona di cambio della propria squadra (propria linea di porta → centro); nelle competizioni World Aquatics c’è anche un <strong>arbitro VAR</strong>.',
      'basics.poolTitle':'La vasca & le sue linee',
      'basics.poolB1':'Campo di gioco: <strong>25 m × 20 m</strong> da linea di porta a linea di porta — uguale per uomini e donne (regole 2025).',
      'basics.poolB2':'<strong>Linea di porta</strong> · <strong>Linea dei 2 m (rossa)</strong> — nessun attaccante può restare dentro di essa prima della palla.',
      'basics.poolB3':'<strong>Linea dei 5 m (gialla)</strong> — i rigori si battono da un punto qualsiasi di questa linea. <strong>Linea dei 6 m (verde)</strong> — i tiri liberi assegnati fuori da questa linea si possono tirare direttamente; si può respingere con due mani solo dentro la propria area dei 6 m.',
      'basics.poolB4':'<strong>Linea di metà campo</strong> al centro. I giocatori espulsi aspettano e rientrano dall’<strong>angolo di espulsione / rientro</strong>.',
      'basics.foulsTitle':'Falli & sanzioni',
      'basics.foulsB1':'<strong>Falli semplici</strong> — affondare la palla, toccarla con due mani (giocatori di movimento), ostacolare un avversario senza palla — danno un <strong>tiro libero / cambio di possesso</strong>.',
      'basics.foulsB2':'<strong>Falli gravi (espulsione)</strong> — trattenere o affondare un avversario, falli tattici — mandano il colpevole nell’angolo di rientro per <strong>18 secondi</strong> (una “superiorità numerica”); rientra al primo di questi eventi: 18 s scontati, un gol, oppure un tiro libero / una rimessa di porta / un rigore per la sua squadra.',
      'basics.foulsB3':'Un fallo grave dentro l’<strong>area dei 6 m</strong> che impedisce un gol probabile è un <strong>rigore</strong>, battuto dalla linea dei 5 m — nell’ultimo minuto l’allenatore può scegliere il possesso (tempo riportato a 28 s).',
      'basics.keeperTitle':'Il portiere',
      'basics.keeperB1':'Porta la <strong>calottina rossa</strong> e difende la porta.',
      'basics.keeperB2':'Dentro l’area dei 6 m il portiere può <strong>usare due mani</strong> e (dove si tocca) spingersi dal fondo — cose vietate ai giocatori di movimento.',
      'basics.keeperB3':'Il portiere fa partire il contropiede: un primo passaggio veloce e preciso trasforma la difesa in attacco.',
      'basics.skillsTitle':'Tecnica di base',
      'basics.skillsB1':'<strong>Eggbeater</strong> — la pedalata alternata delle gambe che ti tiene alto e stabile senza usare le mani.',
      'basics.skillsB2':'<strong>Passaggio a secco</strong> — prendi e rilanci con una mano sola, tenendo la palla fuori dall’acqua.',
