      'film.detectorColour':'● colore',
      'film.trackingNote':'Legge le calottine (bianche / scure / portiere&nbsp;rosso) e la palla arancione e le riporta sulla tua lavagna. Calibra una volta cliccando i quattro angoli del campo di gioco. <strong>Rinforzato</strong> traccia un breve spezzone dal punto attuale e copre le occlusioni. Offline &amp; privato.',
