      'film.scoutIdle':'● inattivo',
      'film.autoScoutNote':'Il sistema guarda <strong>tutto</strong> il video, lo divide in possessi, riconosce ogni tattica e scrive un riassunto di scouting + un playbook — senza segnare niente a mano. Prima calibra la vasca. I video lunghi girano in secondo piano.',
